DO $$ BEGIN CREATE TYPE public.legal_failure_action AS ENUM ('block_booking','block_dispatch','block_settlement','block_processing','block_activation','manual_review','warn_only'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.legal_gate_stage AS ENUM ('serviceability','quote','booking','dispatch','custody','delivery','claims','settlement','processing','activation','invoicing'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.legal_goods_class AS ENUM ('standard','restricted','conditional','prohibited','unknown'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.legal_review_outcome AS ENUM ('pending','legal_review_required','evidence_required','approved','approved_with_conditions','rejected','not_applicable'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.noc_incident_status AS ENUM ('open','investigating','identified','monitoring','resolved','postmortem'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.noc_severity AS ENUM ('SEV1','SEV2','SEV3','SEV4','SEV5'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.partner_wl_incident_status AS ENUM ('open','mitigating','monitoring','resolved','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.partner_wl_tenant_status AS ENUM ('draft','provisioning','certifying','live','suspended'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.security_severity AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.academy_courses ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL DEFAULT '', track text NOT NULL DEFAULT 'workspace', level text NOT NULL DEFAULT 'foundation', audience_roles text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','retired')), version integer NOT NULL DEFAULT 1, estimated_minutes integer NOT NULL DEFAULT 0, sort_order numeric NOT NULL DEFAULT 100, is_mandatory boolean NOT NULL DEFAULT false, changelog text NOT NULL DEFAULT '', published_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.incident_nocs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), incident_code TEXT NOT NULL UNIQUE, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', title TEXT NOT NULL, summary TEXT, affected_services TEXT[], affected_countries TEXT[], blast_radius_pct NUMERIC(5,2), detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), acknowledged_at TIMESTAMPTZ, mitigated_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, incident_commander UUID, comms_lead UUID, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.incident_runbooks ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), runbook_key TEXT NOT NULL UNIQUE, title TEXT NOT NULL, category TEXT NOT NULL, trigger_conditions JSONB, steps JSONB NOT NULL, owner TEXT, last_validated_at TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_jurisdictions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, country_code text NOT NULL, parent_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, notes text, status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_model_registry ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_name TEXT NOT NULL, version TEXT NOT NULL, framework TEXT, use_case TEXT NOT NULL, artifact_uri TEXT, input_schema JSONB, output_schema JSONB, training_metrics JSONB NOT NULL DEFAULT '{}'::jsonb, validation_metrics JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'registered', registered_by UUID, approved_by UUID, approved_at TIMESTAMPTZ, notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(model_name, version) );
CREATE TABLE IF NOT EXISTS public.partner_support_kb_articles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, category text, body text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_support_tickets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_no text NOT NULL UNIQUE DEFAULT ('PST-' || upper(substr(gen_random_uuid()::text,1,8))), partner_id uuid, partner_name text, partner_category text, portal text, category text NOT NULL CHECK (category IN ('ACCOUNT_ACCESS','PARTNER_PROFILE','PORTAL_UI','DATA','BOOKING_QUOTATION','INTEGRATION','DEVICE_BROWSER','PERMISSIONS','OPERATIONAL','SECURITY')), severity text NOT NULL DEFAULT 'MEDIUM' CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), priority text NOT NULL DEFAULT 'P3' CHECK (priority IN ('P1','P2','P3','P4')), status text NOT NULL DEFAULT 'NEW' CHECK (status IN ('NEW','TRIAGED','ASSIGNED','IN_PROGRESS','WAITING_FOR_PARTNER','ESCALATED','RESOLVED','CLOSED')), escalation_level text NOT NULL DEFAULT 'L1' CHECK (escalation_level IN ('L1','L2','L3','SECURITY','OPERATIONS')), escalated_to text, subject text NOT NULL, description text, troubleshooting_notes text, resolution text, kb_article_id uuid, assigned_to uuid, reported_by uuid, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_tenants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, tenant_code text NOT NULL UNIQUE, display_name text NOT NULL, environment public.partner_api_environment NOT NULL DEFAULT 'sandbox', status public.partner_wl_tenant_status NOT NULL DEFAULT 'draft', markets text[] NOT NULL DEFAULT '{}', services text[] NOT NULL DEFAULT '{}', certified_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.safety_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, rider_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, event_type TEXT NOT NULL CHECK (event_type IN ('SOS','INCIDENT','HARSH_DRIVING','ROUTE_DEVIATION','PANIC','MEDICAL','THEFT','ACCIDENT')), severity TEXT NOT NULL DEFAULT 'MEDIUM' CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ACKNOWLEDGED','RESOLVED','CLOSED')), location_lat NUMERIC(10,7), location_lng NUMERIC(10,7), details JSONB NOT NULL DEFAULT '{}'::jsonb, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.security_incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_type text NOT NULL, severity public.security_severity NOT NULL DEFAULT 'MEDIUM', subject_user_id uuid, description text NOT NULL, detected_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, status text NOT NULL DEFAULT 'OPEN', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.service_incidents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), incident_number TEXT NOT NULL UNIQUE DEFAULT ('INC-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), service_name TEXT NOT NULL, title TEXT NOT NULL, severity public.noc_severity NOT NULL DEFAULT 'SEV3', status public.noc_incident_status NOT NULL DEFAULT 'open', impact_summary TEXT, detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), acknowledged_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, commander UUID REFERENCES auth.users(id) ON DELETE SET NULL, postmortem_url TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.support_cases ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_number text NOT NULL UNIQUE DEFAULT ('CASE-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), channel text NOT NULL DEFAULT 'app', category text NOT NULL DEFAULT 'general', subcategory text, priority text NOT NULL DEFAULT 'medium', severity text NOT NULL DEFAULT 'sev3', status text NOT NULL DEFAULT 'new', subject text NOT NULL, description text, requester_user_id uuid, requester_name text, requester_email text, requester_phone text, rider_id uuid, driver_id uuid, corporate_account_id uuid, trip_id uuid, delivery_id uuid, payment_reference text, refund_request_id uuid, assigned_to uuid, assigned_team text, sla_response_due_at timestamptz, sla_resolution_due_at timestamptz, first_response_at timestamptz, resolved_at timestamptz, closed_at timestamptz, sla_response_breached boolean NOT NULL DEFAULT false, sla_resolution_breached boolean NOT NULL DEFAULT false, escalation_level int NOT NULL DEFAULT 0, fraud_risk_score int NOT NULL DEFAULT 0, sentiment text, satisfaction_score int, resolution_notes text, tags text[] NOT NULL DEFAULT '{}', source_reference text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT support_cases_priority_chk CHECK (priority IN ('low','medium','high','urgent')), CONSTRAINT support_cases_severity_chk CHECK (severity IN ('sev1','sev2','sev3','sev4')), CONSTRAINT support_cases_status_chk CHECK (status IN ('new','triaged','assigned','in_progress','pending_customer','pending_approval','escalated','resolved','closed','cancelled')), CONSTRAINT support_cases_channel_chk CHECK (channel IN ('app','email','phone','whatsapp','chatbot','corporate_portal','social','internal')) );
CREATE TABLE IF NOT EXISTS public.support_sla_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL, priority text NOT NULL, response_minutes int NOT NULL DEFAULT 60, resolution_minutes int NOT NULL DEFAULT 1440, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (category, priority) );
CREATE TABLE IF NOT EXISTS public.trust_incidents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID REFERENCES public.trust_cases(id) ON DELETE SET NULL, source TEXT NOT NULL, source_ref UUID, category public.trust_case_category NOT NULL, severity public.trust_case_severity NOT NULL DEFAULT 'medium', subject_type public.trust_subject_type NOT NULL, subject_id UUID, reported_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, description TEXT, evidence_refs JSONB NOT NULL DEFAULT '[]'::JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), routed_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.academy_modules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE, code text NOT NULL, title text NOT NULL, summary text NOT NULL DEFAULT '', sort_order numeric NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (course_id, code) );
CREATE TABLE IF NOT EXISTS public.incident_postmortems ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), incident_id UUID NOT NULL REFERENCES public.incident_nocs(id) ON DELETE CASCADE, summary TEXT NOT NULL, root_cause TEXT, contributing_factors TEXT[], customer_impact TEXT, what_went_well TEXT, what_went_poorly TEXT, action_items JSONB NOT NULL DEFAULT '[]'::jsonb, authored_by UUID, reviewed_by UUID, published_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_regulators ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, domain text, website text, contact_email text, contact_phone text, notes text, status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_predictions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_id UUID REFERENCES public.ml_model_registry(id) ON DELETE SET NULL, use_case TEXT NOT NULL, entity_type TEXT, entity_id TEXT, input_hash TEXT, input_payload JSONB, output JSONB, confidence NUMERIC(5,4), latency_ms INTEGER, served_environment TEXT, request_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.moc_incident_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), incident_id UUID REFERENCES public.incident_nocs(id) ON DELETE CASCADE, incident_code TEXT, event_type TEXT NOT NULL, actor TEXT, channel TEXT, target TEXT, runbook_key TEXT, latency_ms INTEGER, succeeded BOOLEAN, payload JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_incidents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, reference text NOT NULL, severity text NOT NULL DEFAULT 'sev3', title text NOT NULL, detail text, status public.partner_wl_incident_status NOT NULL DEFAULT 'open', correlation_id text, opened_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, resolved_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.support_case_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.support_cases(id) ON DELETE CASCADE, actor_user_id uuid, action text NOT NULL, from_value text, to_value text, note text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.support_case_notes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.support_cases(id) ON DELETE CASCADE, author_user_id uuid, body text NOT NULL, visibility text NOT NULL DEFAULT 'internal', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT support_case_notes_visibility_chk CHECK (visibility IN ('internal','customer')) );
CREATE TABLE IF NOT EXISTS public.academy_lessons ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.academy_modules(id) ON DELETE CASCADE, code text NOT NULL, title text NOT NULL, body_md text NOT NULL DEFAULT '', route_path text, minutes integer NOT NULL DEFAULT 5, sort_order numeric NOT NULL DEFAULT 100, resources jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (module_id, code) );
CREATE TABLE IF NOT EXISTS public.legal_frameworks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, title text NOT NULL, jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, regulator_id uuid REFERENCES public.legal_regulators(id) ON DELETE SET NULL, legal_source text, source_url text, summary text, effective_from date, effective_until date, status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_prediction_feedback ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), prediction_id UUID REFERENCES public.ml_predictions(id) ON DELETE CASCADE, outcome JSONB NOT NULL, reward NUMERIC, is_correct BOOLEAN, source TEXT, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}'::jsonb );
CREATE TABLE IF NOT EXISTS public.academy_feedback ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, course_id uuid REFERENCES public.academy_courses(id) ON DELETE CASCADE, lesson_id uuid REFERENCES public.academy_lessons(id) ON DELETE CASCADE, rating integer CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_requirements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, title text NOT NULL, description text, jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, regulator_id uuid REFERENCES public.legal_regulators(id) ON DELETE SET NULL, framework_id uuid REFERENCES public.legal_frameworks(id) ON DELETE SET NULL, legal_source text, requirement_type text NOT NULL, applies_to text NOT NULL DEFAULT 'platform', service_families text[] NOT NULL DEFAULT '{}', partner_types text[] NOT NULL DEFAULT '{}', asset_types text[] NOT NULL DEFAULT '{}', goods_classes public.legal_goods_class[] NOT NULL DEFAULT '{}', geographies text[] NOT NULL DEFAULT '{}', mandatory boolean NOT NULL DEFAULT true, effective_from date, effective_until date, verification_method text, evidence_type text, approval_authority text, renewal_period_days integer, failure_action public.legal_failure_action NOT NULL DEFAULT 'manual_review', blocking_stages public.legal_gate_stage[] NOT NULL DEFAULT '{}', owner_role text, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'review_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, evidence_type text NOT NULL, title text NOT NULL, description text, storage_bucket text, storage_path text, content_hash text, issued_at timestamptz, valid_until date, collected_by uuid, verification_status public.legal_review_outcome NOT NULL DEFAULT 'pending', verified_by uuid, verified_at timestamptz, status public.legal_status NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_incidents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_code text NOT NULL UNIQUE, category text NOT NULL, severity text NOT NULL DEFAULT 'medium', title text NOT NULL, description text, regulator_id uuid REFERENCES public.legal_regulators(id) ON DELETE SET NULL, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, legal_basis text, affected_customer_id uuid, affected_partner_id uuid, affected_shipment_ref text, reported_at timestamptz NOT NULL DEFAULT now(), reported_by uuid, owner_user_id uuid, owner_role text, deadline_at timestamptz, resolution text, resolved_by uuid, resolved_at timestamptz, evidence_id uuid REFERENCES public.legal_evidence(id) ON DELETE SET NULL, status public.legal_status NOT NULL DEFAULT 'under_review', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.partner_wl_incidents ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES auth.users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS assigned_at timestamptz, ADD COLUMN IF NOT EXISTS resolution text;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['academy_courses','incident_nocs','incident_runbooks','legal_jurisdictions','ml_model_registry','partner_support_kb_articles','partner_support_tickets','partner_wl_tenants','safety_events','security_incidents','service_incidents','support_cases','support_sla_policies','trust_incidents','academy_modules','incident_postmortems','legal_regulators','ml_predictions','moc_incident_events','partner_wl_incidents','support_case_events','support_case_notes','academy_lessons','legal_frameworks','ml_prediction_feedback','academy_feedback','legal_requirements','legal_evidence','legal_incidents'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''support'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''support'']::public.app_role[]))', t); END LOOP; END $$;
